  1→import { useState, useEffect, useCallback, useRef } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import './ConversationHistory.css';
  4→
  5→interface Conversation {
  6→  id: string;
  7→  title: string | null;
  8→  created_at: string;
  9→  updated_at: string;
 10→}
 11→
 12→interface ConversationHistoryProps {
 13→  activeConversationId: string | null;
 14→  onSelect: (conversationId: string) => void;
 15→  onNew: () => void;
 16→  onDelete: (conversationId: string) => void;
 17→  onRename: (conversationId: string, title: string) => void;
 18→  refreshTrigger: number;
 19→  sessionId: string;
 20→}
 21→
 22→function timeAgo(dateStr: string, t: (key: string, params?: Record<string, string | number>) => string): string {
 23→  const date = new Date(dateStr);
 24→  const now = new Date();
 25→  const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);
 26→  if (seconds < 60) return t('timeJustNow');
 27→  const minutes = Math.floor(seconds / 60);
 28→  if (minutes < 60) return t('timeMinutesAgo', { count: minutes });
 29→  const hours = Math.floor(minutes / 60);
 30→  if (hours < 24) return t('timeHoursAgo', { count: hours });
 31→  const days = Math.floor(hours / 24);
 32→  if (days < 30) return t('timeDaysAgo', { count: days });
 33→  return date.toLocaleDateString();
 34→}
 35→
 36→export function ConversationHistory({
 37→  activeConversationId,
 38→  onSelect,
 39→  onNew,
 40→  onDelete,
 41→  onRename,
 42→  refreshTrigger,
 43→  sessionId,
 44→}: ConversationHistoryProps) {
 45→  const { t } = useTranslation();
 46→  const [conversations, setConversations] = useState<Conversation[]>([]);
 47→  const [editingId, setEditingId] = useState<string | null>(null);
 48→  const [editTitle, setEditTitle] = useState('');
 49→  const editInputRef = useRef<HTMLInputElement>(null);
 50→
 51→  const fetchConversations = useCallback(async () => {
 52→    try {
 53→      const res = await fetch('/api/conversations', {
 54→        headers: { 'X-Session-ID': sessionId },
 55→      });
 56→      if (res.ok) {
 57→        setConversations(await res.json());
 58→      }
 59→    } catch {
 60→      // Sidebar fetch failure: show empty list
 61→    }
 62→  }, [sessionId]);
 63→
 64→  useEffect(() => {
 65→    fetchConversations();
 66→  }, [fetchConversations, refreshTrigger]);
 67→
 68→  useEffect(() => {
 69→    if (editingId && editInputRef.current) {
 70→      editInputRef.current.focus();
 71→      editInputRef.current.select();
 72→    }
 73→  }, [editingId]);
 74→
 75→  const handleRenameSubmit = (id: string) => {
 76→    const trimmed = editTitle.trim();
 77→    if (trimmed) {
 78→      onRename(id, trimmed);
 79→    }
 80→    setEditingId(null);
 81→  };
 82→
 83→  const handleDelete = (e: React.MouseEvent, id: string) => {
 84→    e.stopPropagation();
 85→    if (confirm(t('deleteConversationConfirm'))) {
 86→      onDelete(id);
 87→    }
 88→  };
 89→
 90→  const handleStartRename = (e: React.MouseEvent, id: string, currentTitle: string) => {
 91→    e.stopPropagation();
 92→    setEditingId(id);
 93→    setEditTitle(currentTitle || '');
 94→  };
 95→
 96→  return (
 97→    <div className="conv-history">
 98→      <div className="conv-history__header">
 99→        <span className="conv-history__title">{t('conversations')}</span>
100→        <button className="conv-history__new-btn" onClick={onNew} title={t('newConversation')}>
101→          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
102→            <line x1="12" y1="5" x2="12" y2="19" />
103→            <line x1="5" y1="12" x2="19" y2="12" />
104→          </svg>
105→        </button>
106→      </div>
107→      <div className="conv-history__list">
108→        {conversations.length === 0 ? (
109→          <div className="conv-history__empty">{t('noConversationsYet')}</div>
110→        ) : (
111→          conversations.map((conv) => (
112→            <div
113→              key={conv.id}
114→              className={`conv-history__item ${conv.id === activeConversationId ? 'conv-history__item--active' : ''}`}
115→              onClick={() => onSelect(conv.id)}
116→            >
117→              {editingId === conv.id ? (
118→                <input
119→                  ref={editInputRef}
120→                  className="conv-history__edit-input"
121→                  value={editTitle}
122→                  onChange={(e) => setEditTitle(e.target.value)}
123→                  onBlur={() => handleRenameSubmit(conv.id)}
124→                  onKeyDown={(e) => {
125→                    if (e.key === 'Enter') handleRenameSubmit(conv.id);
126→                    if (e.key === 'Escape') setEditingId(null);
127→                  }}
128→                  onClick={(e) => e.stopPropagation()}
129→                />
130→              ) : (
131→                <>
132→                  <div className="conv-history__item-title">
133→                    {conv.title || t('untitled')}
134→                  </div>
135→                  <div className="conv-history__item-meta">
136→                    <span className="conv-history__item-time">{timeAgo(conv.updated_at, t)}</span>
137→                    <span className="conv-history__item-actions">
138→                      <button
139→                        className="conv-history__action-btn"
140→                        onClick={(e) => handleStartRename(e, conv.id, conv.title || '')}
141→                        title={t('rename')}
142→                      >
143→                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
144→                          <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
145→                          <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
146→                        </svg>
147→                      </button>
148→                      <button
149→                        className="conv-history__action-btn conv-history__action-btn--danger"
150→                        onClick={(e) => handleDelete(e, conv.id)}
151→                        title={t('deleteConversation')}
152→                      >
153→                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
154→                          <polyline points="3 6 5 6 21 6" />
155→                          <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
156→                        </svg>
157→                      </button>
158→                    </span>
159→                  </div>
160→                </>
161→              )}
162→            </div>
163→          ))
164→        )}
165→      </div>
166→    </div>
167→  );
168→}
