376→              flushTimerRef.current = null;
377→            }
378→            flushText();
379→            if (currentTextRef.current.trim()) {
380→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
381→              currentTextRef.current = '';
382→            }
383→            phaseRef.current = 'answer';
384→            setMessages((prev) =>
385→              prev.map((m) =>
386→                m.id === assistantId
387→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
388→                  : m
389→              )
390→            );
391→          },
392→          onToolCall: (pending: ToolCallResult) => {
393→            if (flushTimerRef.current) {
394→              clearTimeout(flushTimerRef.current);
395→              flushTimerRef.current = null;
396→            }
397→            flushText();
398→            if (currentTextRef.current.trim()) {
399→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
400→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
401→              currentTextRef.current = '';
402→            }
403→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
404→            setMessages((prev) =>
405→              prev.map((m) =>
406→                m.id === assistantId
407→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
408→                  : m
409→              )
410→            );
411→          },
412→          onToolResult: (result: ToolCallResult) => {
413→            const pendingIdx = segmentsRef.current.findIndex(
414→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
415→            );
416→            if (pendingIdx !== -1) {
417→              const pending = segmentsRef.current[pendingIdx].toolResult!;
418→              segmentsRef.current[pendingIdx] = {
419→                type: 'tool',
420→                toolResult: {
421→                  ...pending,
422→                  ...result,
423→                  sql: result.sql || pending.sql,
424→                  toolName: result.toolName || pending.toolName,
425→                  command: result.command || pending.command,
426→                  toolInput: result.toolInput || pending.toolInput,
427→                },
428→              };
429→            } else {
430→              segmentsRef.current.push({ type: 'tool', toolResult: result });
431→            }
432→            setMessages((prev) =>
433→              prev.map((m) =>
434→                m.id === assistantId
435→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
436→                  : m
437→              )
438→            );
439→            refreshTables();
440→          },
441→          onSubagentStart: (data) => {
442→            if (flushTimerRef.current) {
443→              clearTimeout(flushTimerRef.current);
444→              flushTimerRef.current = null;
445→            }
446→            flushText();
447→            if (currentTextRef.current.trim()) {
448→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
449→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
450→              currentTextRef.current = '';
451→            }
452→            segmentsRef.current.push({
453→              type: 'subagent_start',
454→              subagentId: data.id,
455→              subagentName: data.name,
456→              text: data.prompt,
457→            });
458→            setMessages((prev) =>
459→              prev.map((m) =>
460→                m.id === assistantId
461→                  ? { ...m, segments: [...segmentsRef.current] }
462→                  : m
463→              )
464→            );
465→          },
466→          onSubagentEnd: (data) => {
467→            segmentsRef.current.push({
468→              type: 'subagent_end',
469→              subagentId: data.id,
470→              subagentName: data.name,
471→              chart_spec: data.chart_spec,
472→              sqlResults: data.sql_results,
473→              text: data.result,
474→            });
475→            setMessages((prev) =>
476→              prev.map((m) =>
477→                m.id === assistantId
478→                  ? { ...m, segments: [...segmentsRef.current] }
479→                  : m
480→              )
481→            );
482→          },
483→          onDone: (newSessionId) => {
484→            if (newSessionId) sessionIdRef.current = newSessionId;
485→            if (flushTimerRef.current) {
486→              clearTimeout(flushTimerRef.current);
487→              flushTimerRef.current = null;
488→            }
489→            flushText();
490→            if (currentTextRef.current.trim()) {
491→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
492→              currentTextRef.current = '';
493→            }
494→            setMessages((prev) =>
495→              prev.map((m) =>
496→                m.id === assistantId
497→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
498→                  : m
499→              )
500→            );
501→            setIsStreaming(false);
502→            abortRef.current = null;
503→          },
504→          onError: (error) => {
505→            if (flushTimerRef.current) {
506→              clearTimeout(flushTimerRef.current);
507→              flushTimerRef.current = null;
508→            }
509→            flushText();
510→            if (currentTextRef.current.trim()) {
511→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
512→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
513→              currentTextRef.current = '';
514→            }
515→            segmentsRef.current.push({ type: 'error', errorMessage: error });
516→            setMessages((prev) =>
517→              prev.map((m) =>
518→                m.id === assistantId
519→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
520→                  : m
521→              )
522→            );
523→            setIsStreaming(false);
524→            abortRef.current = null;
525→          },
526→          onUserQuestion: (data) => {
527→            if (flushTimerRef.current) {
528→              clearTimeout(flushTimerRef.current);
529→              flushTimerRef.current = null;
530→            }
531→            flushText();
532→            if (currentTextRef.current.trim()) {
533→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
534→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
535→              currentTextRef.current = '';
536→            }
537→            segmentsRef.current.push({
538→              type: 'user_question',
539→              questionData: data,
540→            });
541→            setMessages((prev) =>
542→              prev.map((m) =>
543→                m.id === assistantId
544→                  ? { ...m, segments: [...segmentsRef.current] }
545→                  : m
546→              )
547→            );
548→          },
549→        },
550→        controller.signal,
551→        userSessionId,
552→      );
553→    },
554→    [isStreaming, messages, flushText, refreshTables, userSessionId]
555→  );
556→
557→  const deleteMessage = useCallback(
558→    (messageIndex: number) => {
559→      if (isStreaming) return;
560→
561→      // Store remaining messages as history for Langfuse context on next send
562→      setMessages((prev) => {
563→        const remaining = prev.slice(0, messageIndex);
564→        pendingHistoryRef.current = remaining
565→          .filter((m) => m.role === 'user' || m.role === 'assistant')
566→          .map((m) => ({ role: m.role, content: m.content }));
567→        return remaining;
568→      });
569→
570→      // Clear session so next message starts fresh
571→      sessionIdRef.current = null;
572→    },
573→    [isStreaming]
574→  );
575→
576→  const respondToQuestion = useCallback(
577→    async (questionId: string, answers: string[], freeText?: string) => {
578→      // Update the segment to show the user's answer
579→      const segIdx = segmentsRef.current.findIndex(
580→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
581→      );
582→      if (segIdx !== -1) {
583→        segmentsRef.current[segIdx] = {
584→          ...segmentsRef.current[segIdx],
585→          userAnswer: answers,
586→          userFreeText: freeText,
587→        };
588→        setMessages((prev) =>
589→          prev.map((m) =>
590→            m.id === assistantIdRef.current
591→              ? { ...m, segments: [...segmentsRef.current] }
592→              : m
593→          )
594→        );
595→      }
596→
597→      // POST to backend
598→      try {
599→        await fetch('/api/chat/respond', {
600→          method: 'POST',
601→          headers: {
602→            'Content-Type': 'application/json',
603→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
604→          },
605→          body: JSON.stringify({
606→            question_id: questionId,
607→            answers,
608→            free_text: freeText || null,
609→          }),
610→        });
611→      } catch (e) {
612→        console.error('Failed to respond to question:', e);
613→      }
614→    },
615→    [userSessionId]
616→  );
617→
618→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
619→    // Abort any ongoing stream before loading a different conversation
620→    if (abortRef.current) {
621→      abortRef.current.abort();
622→      abortRef.current = null;
623→    }
624→    if (flushTimerRef.current) {
625→      clearTimeout(flushTimerRef.current);
626→      flushTimerRef.current = null;
627→    }
628→
629→    // Always prefer cached messages over API when available.  The cache
630→    // represents the most recent in-memory state (with rich segments,
631→    // streaming data, etc.) which is always fresher and more complete
632→    // than what the backend persisted to SQLite.
633→    let finalMsgs = msgs;
634→    if (incomingConversationId) {
635→      const cached = messagesCacheRef.current.get(incomingConversationId);
636→      if (cached && cached.length > 0 && cached.length >= msgs.length) {
637→        finalMsgs = cached;
638→      }
639→      // Clear used cache entry so stale data doesn't persist forever
640→      messagesCacheRef.current.delete(incomingConversationId);
641→    }
642→
643→    // Save current messages to cache before replacing them.
644→    // Uses functional setMessages to read the latest state without
645→    // needing `messages` in the dependency array.
646→    setMessages(prev => {
647→      if (outgoingConversationId && prev.length > 0) {
648→        // Flush any pending text buffer into the streaming assistant message
649→        const pendingText = textBufferRef.current;
650→        const aId = assistantIdRef.current;
651→
652→        // Build finalized segments including any unflushed text
653→        let finalSegments = [...segmentsRef.current];
654→        const pendingSegmentText = currentTextRef.current + pendingText;
655→        if (pendingSegmentText.trim()) {
656→          const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
657→          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
658→        }
659→
660→        const cleaned = prev.map(m => {
661→          if (m.id === aId && m.isStreaming) {
662→            return {
663→              ...m,
664→              content: m.content + pendingText,
665→              isStreaming: false,
666→              currentPhase: undefined,
667→              segments: finalSegments.length > 0 ? finalSegments : m.segments,
668→            };
669→          }
670→          return m;
671→        });
672→        const toCache = cleaned.filter(m => {
673→          if (m.role === 'assistant' && !m.content?.trim() && (!m.segments || m.segments.length === 0)) {
674→            return false;
675→          }
676→          return true;
677→        });
678→        messagesCacheRef.current.set(outgoingConversationId, toCache);
679→      }
680→      return finalMsgs;
681→    });
682→
683→    setIsStreaming(false);
684→    textBufferRef.current = '';
685→    currentTextRef.current = '';
686→    segmentsRef.current = [];
687→    assistantIdRef.current = '';
688→    phaseRef.current = 'thinking';
689→    sessionIdRef.current = null;
690→    pendingHistoryRef.current = null;
691→  }, []);
692→
693→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
694→    if (abortRef.current) {
695→      abortRef.current.abort();
696→      abortRef.current = null;
697→    }
698→    if (flushTimerRef.current) {
699→      clearTimeout(flushTimerRef.current);
700→      flushTimerRef.current = null;
701→    }
702→    setMessages(prev => {
703→      if (outgoingConversationId && prev.length > 0) {
704→        // Flush pending text and segments into the cached messages
705→        // (same logic as loadMessages cache save)
706→        const pendingText = textBufferRef.current;
707→        const aId = assistantIdRef.current;
708→        let finalSegments = [...segmentsRef.current];
709→        const pendingSegmentText = currentTextRef.current + pendingText;
710→        if (pendingSegmentText.trim()) {
711→          const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
712→          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
713→        }
714→        const cleaned = prev.map(m => {
715→          if (m.id === aId && m.isStreaming) {
716→            return {
717→              ...m,
718→              content: m.content + pendingText,
719→              isStreaming: false,
720→              currentPhase: undefined,
721→              segments: finalSegments.length > 0 ? finalSegments : m.segments,
722→            };
723→          }
724→          return m.isStreaming ? { ...m, isStreaming: false, currentPhase: undefined } : m;
725→        });
726→        const toCache = cleaned.filter(m => {
727→          if (m.role === 'assistant' && !m.content?.trim() && (!m.segments || m.segments.length === 0)) {
728→            return false;
729→          }
730→          return true;
731→        });
732→        messagesCacheRef.current.set(outgoingConversationId, toCache);
733→      }
734→      return [];
735→    });
736→    setIsStreaming(false);
737→    textBufferRef.current = '';
738→    currentTextRef.current = '';
739→    segmentsRef.current = [];
740→    assistantIdRef.current = '';
741→    phaseRef.current = 'thinking';
742→    sessionIdRef.current = null;
743→    pendingHistoryRef.current = null;
744→  }, []);
745→
746→  return (
747→    <AgentContext.Provider
748→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion }}
749→    >
750→      {children}
751→    </AgentContext.Provider>
752→  );
753→}
