411→          },
412→          onToolResult: (result: ToolCallResult) => {
413→            const pendingIdx = segmentsRef.current.findIndex(
414→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
415→            );
416→            if (pendingIdx !== -1) {
417→              const pending = segmentsRef.current[pendingIdx].toolResult!;
418→              segmentsRef.current[pendingIdx] = {
419→                type: 'tool',
420→                toolResult: {
421→                  ...pending,
422→                  ...result,
423→                  sql: result.sql || pending.sql,
424→                  toolName: result.toolName || pending.toolName,
425→                  command: result.command || pending.command,
426→                  toolInput: result.toolInput || pending.toolInput,
427→                },
428→              };
429→            } else {
